contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(uint256 loanID_, address to_) public {
        // Drive P through the public entry point approveTransfer.
        // Read the approval slot before the call (public getter), then after.
        address before_ = c.approvals(loanID_);

        bool reverted;
        try c.approveTransfer(to_, loanID_) {
            reverted = false;
        } catch {
            reverted = true;
        }

        address after_ = c.approvals(loanID_);

        // General rule: if the call succeeds, the approval for that key is exactly `to_`;
        // if it reverts, the approval slot is left unchanged.
        assert((!reverted && after_ == to_) || (reverted && after_ == before_));
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(uint256 loanID_, address to_) public {
        // Read the approval slot before the call via the public getter.
        address before_ = c.approvals(loanID_);

        // Drive P through the public entry point approveTransfer. This call may revert
        // (it only succeeds when msg.sender is the loan's lender), so it must be wrapped
        // in try/catch and is the only deciding call.
        bool reverted;
        try c.approveTransfer(to_, loanID_) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read the approval slot after via the public getter.
        address after_ = c.approvals(loanID_);

        // General rule over all inputs: the call either reverts, in which case the
        // approvals slot at loanID_ is left exactly as it was, or it succeeds, in which
        // case the approvals slot at loanID_ is set exactly to to_.
        assert((reverted && after_ == before_) || (!reverted && after_ == to_));
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(uint256 loanID_, address to_) public {
        // The deciding call; deliberately wrapped so we can observe both outcomes.
        // It may revert (e.g. loanID_ out of range, or caller is not the loan's lender),
        // and on success it sets approvals[loanID_] = to_.
        bool reverted;
        try c.approveTransfer(to_, loanID_) {
            reverted = false;
        } catch {
            reverted = true;
        }

        address approvalsValue = c.approvals(loanID_);

        // General rule independent of whether the caller is the lender: if the call
        // succeeded, the approvals mapping at loanID_ must equal to_; if it reverted,
        // whatever value is there must not be the proposed to_ (unless to_ was already
        // the value, in which case setting it is idempotent and acceptable).
        assert((!reverted && approvalsValue == to_) || (reverted && (approvalsValue != to_ || to_ == address(0))));
    }
}

