contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        uint256 amount_,
        uint256 interest_,
        uint256 loanToCollateral_,
        uint256 duration_,
        uint256 repaid_
    ) public payable {
        // Skip zero division / zero-amount edge cases to keep the rule meaningful.
        require(loanToCollateral_ > 0, "collateral ratio must be positive");
        require(duration_ > 0, "duration must be positive");
        require(amount_ > 0, "amount must be positive");

        // The test contract needs collateral tokens to post and debt tokens to repay.
        // It must already hold enough of both; no minting is possible from here.
        uint256 collat = c.collateralFor(amount_, loanToCollateral_);
        require(c.collateral().balanceOf(address(this)) >= collat, "insufficient collateral");

        // Open a request; this transfers `collat` collateral from the test to c.
        uint256 reqID = c.requestLoan(amount_, interest_, loanToCollateral_, duration_);

        // Clear the request to create a loan funded by the test itself.
        uint256 loanID = c.clearRequest(reqID, true, false);

        // Read the loan's initial state through the public getter.
        ( , uint256 loanAmount, , uint256 loanCollateral, , , , ) = c.loans(loanID);
        require(loanAmount > 0, "empty loan");
        require(loanCollateral > 0, "empty collateral");

        // Bound the repay amount to the outstanding debt so we hit the normal path.
        if (repaid_ > loanAmount) repaid_ = loanAmount;
        require(repaid_ > 0, "repay must be positive");

        // The test needs debt tokens to repay.
        require(c.debt().balanceOf(address(this)) >= repaid_, "insufficient debt");

        // Perform the repayment.
        uint256 returned = c.repayLoan(loanID, repaid_);

        // General rule: the returned amount is exactly the collateral released.
        assert(returned > 0 && returned <= loanCollateral);
    }
}

