    constructor(C _c) { c = _c; }

    function run(
        uint256 amount_,
        uint256 interest_,
        uint256 loanToCollateral_,
        uint256 duration_,
        bool repayDirect_,
        uint256 repaid_
    ) public payable {
        require(duration_ > 0, "duration must be positive");

        uint256 reqID = c.requestLoan(amount_, interest_, loanToCollateral_, duration_);
        uint256 loanID = c.clearRequest(reqID, repayDirect_, false);

        C.Loan memory loan = c.getLoan(loanID);
        uint256 preExpiry = loan.expiry;

        bool reverted;
        try c.repayLoan(loanID, repaid_) {
            reverted = false;
        } catch {
            reverted = true;
        }

        bool expired = block.timestamp > preExpiry;
        assert(reverted == expired || (!reverted && !expired));
    }

    receive() external payable {}
}

