        uint256 createdReqID = c.requestLoan(amount, interest, loanToCollateral, duration);
        require(createdReqID == beforeCount);

        uint256 queryID = reqID % (beforeCount + 1);

        C.Request memory reqBefore = c.getRequest(queryID);
        bool expectedActive = reqBefore.active;

        bool reverted;
        bool result;
        try c.isActive(queryID) returns (bool r) {
            result = r;
            reverted = false;
        } catch {
            reverted = true;
        }

        if (queryID < beforeCount + 1) {
            assert(!reverted);
            assert(result == expectedActive);
        }
    }
}

