    constructor(C _c) { c = _c; }

    function run(uint256 loanID) public {
        // Read approvals[loanID] before the deciding call.
        address beforeApproval = c.approvals(loanID);

        // Attempt transferOwnership; it should revert because msg.sender
        // (this test contract) is never the lender of any loan.
        bool reverted;
        try c.transferOwnership(loanID) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read approvals[loanID] after the call.
        address afterApproval = c.approvals(loanID);

        // GENERAL RULE: transferOwnership reverts for this caller (never the lender),
        // and because it reverts, the approvals mapping entry for loanID is unchanged.
        assert(reverted && afterApproval == beforeApproval);
    }
}

